import { ApiTags } from '@nestjs/swagger';
import {
  BaseCrudController,
  type ICrudControllerService,
} from '../../bases';
import type {
  AdmissionResultsRowDto,
  AdmissionResultsCreateData,
  AdmissionResultsUpdateData,
