import 'reflect-metadata';
import { METHOD_METADATA, PATH_METADATA } from '@nestjs/common/constants';
import { BasePublicContactRequestsController } from './public-contact-requests.controller';

type RouteInfo = { method: string; path: string; handler: string };
type ResponseMock = {
  statusCode: number;
  payload: unknown;
  status: jest.Mock<ResponseMock, [number]>;
  json: jest.Mock<ResponseMock, [unknown]>;
};

function createResponseMock(): ResponseMock {
  const response: ResponseMock = {
    statusCode: 200,
    payload: undefined,
    status: jest.fn((code: number): ResponseMock => {
      response.statusCode = code;
      return response;
    }),
    json: jest.fn((payload: unknown): ResponseMock => {
      response.payload = payload;
      return response;
    }),
  };
  return response;
}

function getRoutes(ctrl: object): RouteInfo[] {
  const out: RouteInfo[] = [];
  const map: Record<number, string> = { 1: 'POST' };
  let proto: object | null = Object.getPrototypeOf(ctrl);
  while (proto && proto !== Object.prototype) {
    for (const name of Object.getOwnPropertyNames(proto)) {
      if (name === 'constructor') continue;
      const handler = Object.getOwnPropertyDescriptor(proto, name)?.value as
        | ((...args: unknown[]) => unknown)
        | undefined;
      if (typeof handler !== 'function') continue;
      const method = Reflect.getMetadata(METHOD_METADATA, handler) as number | undefined;
      const pathMeta = Reflect.getMetadata(PATH_METADATA, handler) as string | undefined;
      if (typeof method !== 'number' || pathMeta == null || !(method in map)) continue;
      out.push({
        method: map[method],
        path: pathMeta === '' ? '/' : `/${String(pathMeta).replace(/^\//, '')}`,
        handler: name,
      });
    }
    proto = Object.getPrototypeOf(proto);
  }
  return out;
}

describe('BasePublicContactRequestsController', () => {
  let service: {
    create: jest.Mock;
  };
  let controller: BasePublicContactRequestsController;

  beforeEach(() => {
    service = {
      create: jest.fn().mockResolvedValue({ id: 123 }),
    };
    controller = new BasePublicContactRequestsController(service as never);
  });

  it('exposes POST /contact-requests (public contract)', () => {
    expect(getRoutes(controller)).toEqual(
      expect.arrayContaining([
        { method: 'POST', path: '/contact-requests', handler: 'createContactRequest' },
      ]),
    );
  });

  it('400 khi thieu name/email va khong co subject/legacy fields', async () => {
    const res = createResponseMock();
    await controller.createContactRequest(
      { email: 'a@b.com' } as never,
      res as never,
    );
    expect(res.status).toHaveBeenCalledWith(400);
  });

  it('tao contact request va tra {id, message} trong success envelope', async () => {
    const res = createResponseMock();
    await controller.createContactRequest(
      {
        fullName: 'User',
        email: 'user@example.com',
        program: 'A',
      } as never,
      res as never,
    );
    expect(service.create).toHaveBeenCalled();
    expect(res.status).toHaveBeenCalledWith(200);
    expect(res.payload).toEqual(
      expect.objectContaining({
        success: true,
        data: expect.objectContaining({
          id: '123',
          message: expect.any(String),
        }),
      }),
    );
  });

  it('500 khi service throw', async () => {
    service.create.mockRejectedValueOnce(new Error('boom'));
    const res = createResponseMock();
    await controller.createContactRequest(
      {
        fullName: 'User',
        email: 'user@example.com',
        subject: 'Help',
      } as never,
      res as never,
    );
    expect(res.status).toHaveBeenCalledWith(500);
  });
});

import { Body, Controller, Post, Res } from '@nestjs/common';
import type { Response } from 'express';
import { Public, createErrorResponse, createSuccessResponse } from '../../common';
import { PUBLIC_ROUTES } from '../../config';
import type { BaseContactRequestsService } from './contact-request.service';

export type CreatePublicContactRequestDto = {
  name?: string;
  fullName?: string;
  email: string;
  phone?: string;
  subject?: string;
  address?: string;
  program?: string;
  major?: string;
  subscribeNewsletter?: boolean;
  subscribeConsultation?: boolean;
  content?: string;
};

export interface IPublicContactRequestsControllerService
  extends Pick<BaseContactRequestsService, 'create'> {}

@Public()
@Controller(PUBLIC_ROUTES.BASE)
export class BasePublicContactRequestsController {
  constructor(private readonly service: IPublicContactRequestsControllerService) {}

  @Post('contact-requests')
  async createContactRequest(
    @Body() body: CreatePublicContactRequestDto,
    @Res() res: Response,
  ): Promise<Response> {
    const name = body?.name?.trim() || body?.fullName?.trim();
    const email = body?.email?.trim();
    const subject = body?.subject?.trim();
    const hasLegacyConsultationFields = Boolean(
      body?.address ||
        body?.program ||
        body?.major ||
        body?.subscribeNewsletter ||
        body?.subscribeConsultation,
    );

    if (!name || !email || (!subject && !hasLegacyConsultationFields)) {
      const { statusCode, body: errBody } = createErrorResponse(
        'Vui long dien day du ho ten, email va chu de lien he.',
        { status: 400 },
      );
      return res.status(statusCode).json(errBody);
    }

    try {
      const resolvedSubject = subject
        ? subject
        : hasLegacyConsultationFields
          ? 'Dang ky tu van tuyen sinh'
          : 'Lien he ho tro';

      const parts: string[] = [];
      if (body.address) parts.push(`Dia chi: ${body.address}`);
      if (body.program) parts.push(`Chuong trinh: ${body.program}`);
      if (body.major) parts.push(`Nganh: ${body.major}`);
      if (body.subscribeNewsletter)
        parts.push('Dang ky nhan thong tin tuyen sinh: Co');
      if (body.subscribeConsultation) parts.push('Dang ky tu van: Co');
      if (body.content?.trim()) parts.push(`Noi dung: ${body.content.trim()}`);
      const content = parts.length > 0 ? parts.join('\n') : 'Khong co noi dung them';

      const created = await this.service.create({
        name,
        email,
        phone: body.phone?.trim() ? body.phone.trim() : null,
        subject: resolvedSubject,
        content,
        status: 'NEW',
        isRead: false,
      } as never);

      const { statusCode, body: okBody } = createSuccessResponse({
        id: String((created as unknown as { id?: string | number }).id ?? ''),
        message: 'Gui lien he thanh cong. Chung toi se phan hoi ban som.',
      });
      return res.status(statusCode).json(okBody);
    } catch {
      const { statusCode, body: errBody } = createErrorResponse(
        'Khong the gui lien he ho tro. Vui long thu lai sau.',
        { status: 500 },
      );
      return res.status(statusCode).json(errBody);
    }
  }
}

