    });

    it('bulk empty ids throws BadRequestException', async () => {
      await expect(controller.bulk({ action: 'delete', ids: [] })).rejects.toThrow(BadRequestException);
    });

    it('bulk non-array ids throws BadRequestException', async () => {
      await expect(
