import type { EntityName } from '@mikro-orm/core';
import type { EventRegistrationRowDto } from './event-registrations-admin.service';
import type { EventAttendanceSocketPayload } from './event-registration-attendance.types';

export interface EventRegistrationAttendanceDeps {
  eventEntity: EntityName<Record<string, unknown>>;
  eventRegistrationEntity: EntityName<Record<string, unknown>>;
  getRegistrationById(id: string): Promise<EventRegistrationRowDto | null>;
  emitAttendance(payload: EventAttendanceSocketPayload): void;
}

/** Event registration attendance — check-in/out; app binding entity, socket emit, getById. */
import {
  BadRequestException,
  Logger,
  NotFoundException,
} from '@nestjs/common';
import { EntityManager, type FilterQuery } from '@mikro-orm/core';
import { relationEntityId, toEntityId } from '../../common/entity-id';
import type { EventRegistrationAttendanceDeps } from './event-registration-attendance.deps';
import type {
  ApplyAttendanceResult,
  AttendanceRegistrationRow,
  AttendanceSource,
  EventAttendancePolicy,
  EventAttendanceSocketPayload,
  ManualAttendanceAction,
} from './event-registration-attendance.types';
import {
  ATTENDANCE_STATUS,
  CHECKIN_METHOD,
  REGISTRATION_STATUS,
} from './event-registration-attendance.types';
import type { EventRegistrationRowDto } from './event-registrations-admin.service';

export class BaseEventRegistrationAttendanceService {
  private readonly logger = new Logger(BaseEventRegistrationAttendanceService.name);

  constructor(
    protected readonly em: EntityManager,
    protected readonly deps: EventRegistrationAttendanceDeps,
  ) {}

  async applyManual(
    registrationId: string,
    action: ManualAttendanceAction,
  ): Promise<EventRegistrationRowDto> {
    const reg = await this.em.findOne(
      this.deps.eventRegistrationEntity,
      {
        id: toEntityId(registrationId),
        deletedAt: null,
      } as FilterQuery<Record<string, unknown>>,
    );
    if (!reg) {
      throw new NotFoundException('Không tìm thấy đăng ký sự kiện');
    }

    const row = reg as unknown as AttendanceRegistrationRow;
    const eventId = relationEntityId(row.event);
    if (eventId == null) {
      throw new BadRequestException('Đăng ký không gắn sự kiện hợp lệ');
    }

    const at = new Date();

    switch (action) {
      case 'checkin': {
        await this.recordCheckin({
          eventId,
          registration: row,
          at,
          source: 'manual',
          skipWindowCheck: true,
        });
        break;
      }
      case 'checkout': {
        await this.recordCheckout({
          eventId,
          registration: row,
          at,
          source: 'manual',
          skipWindowCheck: true,
        });
        break;
      }
      case 'reset-checkin':
        row.hasCheckin = false;
        row.checkinMethod = CHECKIN_METHOD.NONE;
        if (row.hasCheckout) {
          row.hasCheckout = false;
        }
        row.attendanceStatus = ATTENDANCE_STATUS.NOT_ATTENDED;
        row.updatedAt = at;
        await this.em.flush();
        await this.syncEventCounts(eventId);
        this.emitState(row, eventId, 'checkin', 'manual', { duplicate: false });
        break;
      case 'reset-checkout':
        row.hasCheckout = false;
        row.attendanceStatus = row.hasCheckin
          ? ATTENDANCE_STATUS.PARTIAL
          : ATTENDANCE_STATUS.NOT_ATTENDED;
        row.updatedAt = at;
        await this.em.flush();
        await this.syncEventCounts(eventId);
        this.emitState(row, eventId, 'checkout', 'manual', {
          duplicate: false,
        });
        break;
      case 'reset-all':
        row.hasCheckin = false;
        row.hasCheckout = false;
        row.checkinMethod = CHECKIN_METHOD.NONE;
        row.attendanceStatus = ATTENDANCE_STATUS.NOT_ATTENDED;
        row.updatedAt = at;
        await this.em.flush();
        await this.syncEventCounts(eventId);
        this.emitState(row, eventId, 'checkin', 'manual', { duplicate: false });
        break;
      default:
        throw new BadRequestException('Thao tác attendance không hợp lệ');
    }

    const mapped = await this.deps.getRegistrationById(registrationId);
    if (!mapped) {
      throw new NotFoundException('Không tìm thấy đăng ký sự kiện');
    }
    return mapped;
  }

  async recordCheckin(input: {
    eventId: number;
    registration: AttendanceRegistrationRow;
    at: Date;
    source: AttendanceSource;
    deviceId?: string | null;
    deviceName?: string | null;
    skipWindowCheck?: boolean;
  }): Promise<ApplyAttendanceResult> {
    const { eventId, registration: reg, at, source } = input;
    if (!input.skipWindowCheck) {
      const event = await this.loadEvent(eventId);
      this.assertEventAllows(event, 'checkin', at);
    }

    if (reg.hasCheckin) {
      this.logger.debug(
        `Attendance check-in bỏ qua (đã check-in) event=${eventId} email=${reg.email}`,
      );
      const result = await this.toResult(eventId, reg, 'checkin', true);
      this.emitState(reg, eventId, 'checkin', source, {
        duplicate: true,
        deviceId: input.deviceId,
        deviceName: input.deviceName,
      });
      return result;
    }

    reg.hasCheckin = true;
    reg.faceVerified = source === 'hanet' ? true : reg.faceVerified;
    reg.checkinMethod =
      source === 'manual' ? CHECKIN_METHOD.MANUAL : CHECKIN_METHOD.FACE_ID;
    reg.updatedAt = at;
    if (reg.status === REGISTRATION_STATUS.PENDING) {
      reg.status = REGISTRATION_STATUS.CONFIRMED;
    }
    if (reg.attendanceStatus === ATTENDANCE_STATUS.NOT_ATTENDED) {
      reg.attendanceStatus = ATTENDANCE_STATUS.PARTIAL;
    }
    await this.em.flush();
    await this.syncEventCounts(eventId);

    const result = await this.toResult(eventId, reg, 'checkin', false);
    this.emitState(reg, eventId, 'checkin', source, {
      duplicate: false,
      deviceId: input.deviceId,
      deviceName: input.deviceName,
    });
    this.logger.log(
      `Attendance check-in (${source}) event=${eventId} email=${reg.email}`,
    );
    return result;
  }

  async recordCheckout(input: {
    eventId: number;
    registration: AttendanceRegistrationRow;
    at: Date;
    source: AttendanceSource;
    skipWindowCheck?: boolean;
  }): Promise<ApplyAttendanceResult> {
    const { eventId, registration: reg, at, source } = input;
    if (!input.skipWindowCheck) {
      const event = await this.loadEvent(eventId);
      this.assertEventAllows(event, 'checkout', at);
    }

    if (reg.hasCheckout) {
      this.logger.debug(
        `Attendance check-out bỏ qua (đã check-out) event=${eventId} email=${reg.email}`,
      );
      const result = await this.toResult(eventId, reg, 'checkout', true);
      this.emitState(reg, eventId, 'checkout', source, { duplicate: true });
      return result;
    }

    if (!reg.hasCheckin) {
      reg.hasCheckin = true;
      if (reg.attendanceStatus === ATTENDANCE_STATUS.NOT_ATTENDED) {
        reg.attendanceStatus = ATTENDANCE_STATUS.PARTIAL;
      }
    }

    reg.hasCheckout = true;
    reg.faceVerified = source === 'hanet' ? true : reg.faceVerified;
    reg.attendanceStatus = ATTENDANCE_STATUS.FULL;
    reg.updatedAt = at;
    await this.em.flush();
    await this.syncEventCounts(eventId);

    const result = await this.toResult(eventId, reg, 'checkout', false);
    this.emitState(reg, eventId, 'checkout', source, { duplicate: false });
    this.logger.log(
      `Attendance check-out (${source}) event=${eventId} email=${reg.email}`,
    );
    return result;
  }

  private async loadEvent(eventId: number): Promise<EventAttendancePolicy> {
    const event = await this.em.findOne(this.deps.eventEntity, {
      id: eventId,
      deletedAt: null,
    } as FilterQuery<Record<string, unknown>>);
    if (!event) {
      throw new NotFoundException('Không tìm thấy sự kiện');
    }
    return event as unknown as EventAttendancePolicy;
  }

  private assertEventAllows(
    event: EventAttendancePolicy,
    kind: 'checkin' | 'checkout',
    at: Date,
  ): void {
    if (kind === 'checkin' && !event.allowCheckin) {
      throw new BadRequestException('Sự kiện không cho phép check-in');
    }
    if (kind === 'checkout' && !event.allowCheckout) {
      throw new BadRequestException('Sự kiện không cho phép check-out');
    }

    const within = (start?: Date | null, end?: Date | null) => {
      if (start && at < start) return false;
      if (end && at > end) return false;
      return true;
    };

    if (kind === 'checkin') {
      if (
        (event.checkinStart || event.checkinEnd) &&
        !within(event.checkinStart, event.checkinEnd)
      ) {
        throw new BadRequestException(
          'Thời điểm check-in nằm ngoài khung giờ cho phép',
        );
      }
      return;
    }

    const windowStart = event.checkoutStart ?? event.checkinEnd ?? null;
    const windowEnd = event.checkoutEnd ?? event.endDate ?? null;
    if ((windowStart || windowEnd) && !within(windowStart, windowEnd)) {
      throw new BadRequestException(
        'Thời điểm check-out nằm ngoài khung giờ cho phép',
      );
    }
  }

  private async syncEventCounts(eventId: number): Promise<void> {
    const checkinCount = await this.em.count(this.deps.eventRegistrationEntity, {
      event: eventId,
      hasCheckin: true,
      deletedAt: null,
    } as FilterQuery<Record<string, unknown>>);
    const checkoutCount = await this.em.count(this.deps.eventRegistrationEntity, {
      event: eventId,
      hasCheckout: true,
      deletedAt: null,
    } as FilterQuery<Record<string, unknown>>);
    await this.em.nativeUpdate(
      this.deps.eventEntity,
      { id: eventId },
      { totalCheckins: checkinCount, totalCheckouts: checkoutCount },
    );
  }

  private async toResult(
    eventId: number,
    reg: AttendanceRegistrationRow,
    kind: 'checkin' | 'checkout',
    duplicate: boolean,
  ): Promise<ApplyAttendanceResult> {
    const mapped = await this.deps.getRegistrationById(String(reg.id));
    if (!mapped) {
      throw new NotFoundException('Không tìm thấy đăng ký sự kiện');
    }
    return {
      kind,
      eventId,
      email: reg.email,
      fullName: reg.fullName,
      registrationId: reg.id,
      at: reg.updatedAt.toISOString(),
      duplicate,
      registration: mapped,
    };
  }

  private emitState(
    reg: AttendanceRegistrationRow,
    eventId: number,
    kind: 'checkin' | 'checkout',
    source: AttendanceSource,
    extra: {
      duplicate?: boolean;
      deviceId?: string | null;
      deviceName?: string | null;
    },
  ): void {
    const payload: EventAttendanceSocketPayload = {
      kind,
      eventId,
      at: reg.updatedAt.toISOString(),
      email: reg.email,
      fullName: reg.fullName,
      source,
      deviceId: extra.deviceId ?? null,
      deviceName: extra.deviceName ?? null,
      registrationId: reg.id,
      checkinId: null,
      duplicate: extra.duplicate,
      hasCheckin: reg.hasCheckin,
      hasCheckout: reg.hasCheckout,
    };
    this.deps.emitAttendance(payload);
  }
}

import type { EventRegistrationRowDto } from './event-registrations-admin.service';

export type AttendanceSource = 'hanet' | 'manual';

export type ManualAttendanceAction =
  | 'checkin'
  | 'checkout'
  | 'reset-checkin'
  | 'reset-checkout'
  | 'reset-all';

export type ApplyAttendanceResult = {
  kind: 'checkin' | 'checkout';
  eventId: number;
  email: string;
  fullName: string;
  registrationId: number;
  at: string;
  duplicate?: boolean;
  registration: EventRegistrationRowDto;
};

export type EventAttendanceSocketPayload = {
  kind: 'checkin' | 'checkout';
  eventId: number;
  at: string;
  email: string;
  fullName: string;
  source: AttendanceSource;
  deviceId?: string | null;
  deviceName?: string | null;
  registrationId?: string | number | null;
  checkinId?: string | null;
  duplicate?: boolean;
  hasCheckin?: boolean;
  hasCheckout?: boolean;
};

/** Khớp `RegistrationStatus` entity. */
export const REGISTRATION_STATUS = {
  PENDING: 0,
  CONFIRMED: 1,
  CANCELLED: 2,
} as const;

/** Khớp `AttendanceStatus` entity. */
export const ATTENDANCE_STATUS = {
  NOT_ATTENDED: 0,
  PARTIAL: 1,
  FULL: 2,
} as const;

/** Khớp `CheckinMethod` entity. */
export const CHECKIN_METHOD = {
  NONE: 0,
  QR_CODE: 1,
  FACE_ID: 2,
  MANUAL: 3,
} as const;

export type EventAttendancePolicy = {
  allowCheckin: boolean;
  allowCheckout: boolean;
  checkinStart?: Date | null;
  checkinEnd?: Date | null;
  checkoutStart?: Date | null;
  checkoutEnd?: Date | null;
  endDate?: Date | null;
};

export type AttendanceRegistrationRow = {
  id: number;
  email: string;
  fullName: string;
  event: unknown;
  hasCheckin: boolean;
  hasCheckout: boolean;
  faceVerified: boolean;
  checkinMethod: number;
  attendanceStatus: number;
  status: number;
  updatedAt: Date;
};

/**
 * Controller spec cho EventRegistration controller.
 *
 * Sinh tự động bởi `generate-controller-specs.cjs`. Mục tiêu:
 *   - 100% statement/branch coverage cho file controller tương ứng.
 *   - Validate contract mà `packages/api-client` đang dùng:
 *     route + envelope + filter[column] + hard-delete alias.
 *
 * Không spin Nest app: khởi tạo controller instance với service mock và
 * đọc route metadata qua `Reflect`. Đủ để phát hiện mismatch giữa client
 * và server.
 */
import 'reflect-metadata';
import {
  BadRequestException,
  NotFoundException,
  RequestMethod,
} from '@nestjs/common';
import {
  METHOD_METADATA,
  PATH_METADATA,
} from '@nestjs/common/constants';
import { BaseEventRegistrationsController } from './event-registration.controller';
import type { ICrudControllerService, BulkOperationResult, ListCrudParams, PaginatedResult, CrudRowDto } from '../../bases';

class TestRow implements CrudRowDto {
  id!: number;
  title = '';
  deletedAt: string | null = null;
  createdAt = new Date().toISOString();
  updatedAt = new Date().toISOString();
}

type ReqHandler = (req: unknown, res?: unknown, next?: unknown) => unknown;
type RouteInfo = { method: string; path: string; handler: string };

class TestController extends BaseEventRegistrationsController {
  constructor(
    service: ICrudControllerService<TestRow> & {
      applyManualAttendance: (
        id: string | number,
        action: string,
      ) => Promise<TestRow>;
    },
  ) {
    super(service as never);
  }
}

describe('BaseEventRegistrationsController — client contract', () => {
  let controller: TestController;
  let service: jest.Mocked<ICrudControllerService<TestRow>> & {
    applyManualAttendance: jest.Mock;
  };
  const sampleRow: TestRow = {
    id: 1,
    title: 'sample',
    deletedAt: null,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };

  function getRoutes(ctrl: object): RouteInfo[] {
    const out: RouteInfo[] = [];
    // Map RequestMethod enum number → verb name.
    // RequestMethod: GET=0, POST=1, PUT=2, DELETE=3, PATCH=4, OPTIONS=9, HEAD=5, SEARCH=6, ALL=7
    const VERB_MAP: Record<number, string> = {
      0: 'GET',
      1: 'POST',
      2: 'PUT',
      3: 'DELETE',
      4: 'PATCH',
      5: 'HEAD',
      6: 'SEARCH',
      7: 'ALL',
      9: 'OPTIONS',
    };
    // Walk up the prototype chain vì decorator metadata có thể
    // được đăng ký ở BaseCrudController.
    const seen = new Set<string>();
    let proto: object | null = Object.getPrototypeOf(ctrl);
    while (proto && proto !== Object.prototype) {
      for (const name of Object.getOwnPropertyNames(proto)) {
        if (name === 'constructor') continue;
        if (seen.has(name)) continue;
        seen.add(name);
        const desc = Object.getOwnPropertyDescriptor(proto, name);
        if (!desc) continue;
        const handler = desc.value as ReqHandler | undefined;
        if (typeof handler !== 'function') continue;
        const verb = Reflect.getMetadata(METHOD_METADATA, handler) as number | undefined;
        if (typeof verb !== 'number') continue;
        const verbName = VERB_MAP[verb];
        if (!verbName) continue;
        const pathMeta = Reflect.getMetadata(PATH_METADATA, handler) as
          | string
          | string[]
          | undefined;
        if (pathMeta == null) continue;
        const normalized = Array.isArray(pathMeta) ? pathMeta[0] : pathMeta;
        const cleanPath =
          normalized === '' ? '/' : `/${String(normalized).replace(/^\//, '')}`;
        out.push({ method: verbName, path: cleanPath, handler: name });
      }
      proto = Object.getPrototypeOf(proto);
    }
    return out;
  }

  beforeEach(() => {
    service = {
      list: jest.fn(async () => ({
        data: [sampleRow],
        pagination: { page: 1, limit: 10, total: 1, totalPages: 1 },
      })),
      getById: jest.fn(async (id) => ({ ...sampleRow, id: Number(id) })),
      create: jest.fn(async (data) => ({ ...sampleRow, ...(data as object) } as TestRow)),
      update: jest.fn(async (id, data) => ({ ...sampleRow, id: Number(id), ...(data as object) } as TestRow)),
      softDelete: jest.fn(async () => true),
      restore: jest.fn(async () => true),
      hardDelete: jest.fn(async () => true),
      bulk: jest.fn(async (_a, ids) => ({
        success: ids.length,
        failed: 0,
        total: ids.length,
        errors: [],
        message: 'ok',
      })),
      applyManualAttendance: jest.fn(async (id) => ({
        ...sampleRow,
        id: Number(id),
      })),
    } as typeof service;
    controller = new TestController(service);
  });

  // ─────────────────────────────────────────────────────────
  // 1) Route metadata
  // ─────────────────────────────────────────────────────────
  describe('route metadata (api-client contract)', () => {
    it('exposes GET / (list)', () => {
      const r = getRoutes(controller).find((x) => x.handler === 'list');
      expect(r?.method).toBe('GET');
      expect(r?.path).toBe('/');
    });

    it('exposes GET /:id (getById)', () => {
      const r = getRoutes(controller).find((x) => x.handler === 'getById');
      expect(r?.method).toBe('GET');
      expect(r?.path).toBe('/:id');
    });

    it('exposes POST / (create)', () => {
      const r = getRoutes(controller).find((x) => x.handler === 'create');
      expect(r?.method).toBe('POST');
      expect(r?.path).toBe('/');
    });

    it('exposes PUT /:id (update)', () => {
      const r = getRoutes(controller).find((x) => x.handler === 'update');
      expect(r?.method).toBe('PUT');
      expect(r?.path).toBe('/:id');
    });

    it('exposes DELETE /:id (softDelete)', () => {
      const r = getRoutes(controller).find((x) => x.handler === 'softDelete');
      expect(r?.method).toBe('DELETE');
      expect(r?.path).toBe('/:id');
    });

    it('exposes POST /:id/restore (restore)', () => {
      const r = getRoutes(controller).find((x) => x.handler === 'restore');
      expect(r?.method).toBe('POST');
      expect(r?.path).toBe('/:id/restore');
    });

    it('exposes DELETE /:id/hard (hardDelete)', () => {
      const r = getRoutes(controller).find((x) => x.handler === 'hardDelete');
      expect(r?.method).toBe('DELETE');
      expect(r?.path).toBe('/:id/hard');
    });

    it('exposes DELETE /:id/hard-delete (alias cho api-client.purge)', () => {
      const r = getRoutes(controller).find((x) => x.handler === 'hardDeleteAlias');
      expect(r?.method).toBe('DELETE');
      expect(r?.path).toBe('/:id/hard-delete');
    });

    it('exposes POST /bulk (bulk)', () => {
      const r = getRoutes(controller).find((x) => x.handler === 'bulk');
      expect(r?.method).toBe('POST');
      expect(r?.path).toBe('/bulk');
    });

    it('exposes POST /:id/attendance (api-client.setAttendance)', () => {
      const r = getRoutes(controller).find((x) => x.handler === 'setAttendance');
      expect(r?.method).toBe('POST');
      expect(r?.path).toBe('/:id/attendance');
    });
  });

  // ─────────────────────────────────────────────────────────
  // 2) Envelope + happy path
  // ─────────────────────────────────────────────────────────
  describe('envelope contract (api-client.unwrapApiEnvelope)', () => {
    it('list trả về success envelope với paginated data', async () => {
      const result = await controller.list({});
      expect(result).toEqual({
        success: true,
        message: expect.any(String),
        error: null,
        data: {
          data: [sampleRow],
