/**
 * EventRegistrations Controller.
 *
 * Bám sát pattern của `apps/main/api/src/event-registrations/event-registrations.controller.ts`.
 */
import {
  Post,
  Param,
  Body,
  HttpCode,
  HttpStatus,
  BadRequestException,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiParam, ApiResponse } from '@nestjs/swagger';
import {
  BaseCrudController,
  type ICrudControllerService,
} from '../../bases';
import {
  createSuccessResponse,
  createErrorResponse,
  type ApiResponsePayload,
} from '../../common';
import type {
  EventRegistrationsRowDto,
  EventRegistrationsCreateData,
  EventRegistrationsUpdateData,
} from './event-registration.service';

export type ManualAttendanceAction =
  | 'checkin'
  | 'checkout'
  | 'reset-checkin'
  | 'reset-checkout'
  | 'reset-all';

const MANUAL_ATTENDANCE_ACTIONS = new Set<ManualAttendanceAction>([
  'checkin',
  'checkout',
  'reset-checkin',
  'reset-checkout',
  'reset-all',
]);

export interface IEventRegistrationsControllerService
  extends ICrudControllerService<
    EventRegistrationsRowDto,
    EventRegistrationsCreateData,
    EventRegistrationsUpdateData
  > {
  applyManualAttendance(
    id: string | number,
    action: ManualAttendanceAction,
  ): Promise<EventRegistrationsRowDto>;
}

@ApiTags('EventRegistrations')
export class BaseEventRegistrationsController extends BaseCrudController<
  EventRegistrationsRowDto,
  EventRegistrationsCreateData,
  EventRegistrationsUpdateData
> {
  private readonly eventRegistrationsService: IEventRegistrationsControllerService;

  constructor(service: IEventRegistrationsControllerService) {
    super(service, 'event-registrations');
    this.eventRegistrationsService = service;
  }

  /**
   * POST /event-registrations/:id/attendance — khớp api-client.setAttendance().
   */
  @Post(':id/attendance')
  @HttpCode(HttpStatus.OK)
  @ApiOperation({
    summary:
      'Cập nhật trạng thái check-in/out thủ công (khi socket lỗi hoặc điều chỉnh)',
  })
  @ApiParam({ name: 'id', type: String })
  @ApiResponse({ status: 200, description: 'Registration row after attendance update' })
  @ApiResponse({ status: 400, description: 'Invalid action' })
  @ApiResponse({ status: 404, description: 'Registration not found' })
  async setAttendance(
    @Param('id') id: string,
    @Body() body: { action?: ManualAttendanceAction },
  ): Promise<ApiResponsePayload<EventRegistrationsRowDto>> {
    const action = body?.action;
    if (!action || !MANUAL_ATTENDANCE_ACTIONS.has(action)) {
      throw new BadRequestException(
        createErrorResponse(
          'action phải là checkin | checkout | reset-checkin | reset-checkout | reset-all',
          { status: 400 },
        ).body,
      );
    }
    const updated = await this.eventRegistrationsService.applyManualAttendance(
      id,
      action,
    );
    return createSuccessResponse(updated).body;
  }
}

import 'reflect-metadata';
import * as Subject from './event-registration.module';

describe('event-registration.module.ts', () => {
  it('exports at least one Module class', () => {
    const keys = Object.keys(Subject);
    expect(keys.some((key) => key.endsWith('Module'))).toBe(true);
  });

  it('forRoot keeps metadata and appends controller when available', () => {
    const moduleKey = Object.keys(Subject).find((key) => key.endsWith('Module'));
    expect(moduleKey).toBeTruthy();
    const ModuleClass = Subject[moduleKey];
    expect(typeof ModuleClass.forRoot).toBe('function');

    const controllerKey = Object.keys(Subject).find((key) => key.endsWith('Controller'));
    const ExtraController = class ExtraController {};
    const ImportedModule = class ImportedModule {};
    const provider = { provide: 'TOKEN', useValue: 1 };

    const metadata = ModuleClass.forRoot({
      imports: [ImportedModule],
      controllers: [ExtraController],
      providers: [provider],
      exports: ['TOKEN'],
    });

    expect(metadata.imports).toEqual([ImportedModule]);
    expect(metadata.providers).toEqual([provider]);
    expect(metadata.exports).toEqual(['TOKEN']);
    expect(metadata.controllers).toEqual(
      expect.arrayContaining(
        controllerKey ? [ExtraController, Subject[controllerKey]] : [ExtraController],
      ),
    );
  });

  it('forRoot works with default metadata', () => {
    const moduleKey = Object.keys(Subject).find((key) => key.endsWith('Module'));
    const ModuleClass = Subject[moduleKey];
    const metadata = ModuleClass.forRoot();
    expect(metadata.imports).toEqual([]);
    expect(Array.isArray(metadata.controllers)).toBe(true);
    expect(metadata.providers).toEqual([]);
    expect(metadata.exports).toEqual([]);
  });
});

