  const fixtureRows = (fixture as unknown as Record<string, Array<Record<string, unknown>>>).majors ?? [];

  beforeAll(() => {
    em = createFakeEntityManager(fixture);
    service = new TestMajorsServiceIntegrationService(em);
  });

  beforeEach(() => {
