  UnauthorizedException,
  ForbiddenException,
  Delete,
  Post,
  Controller,
  Logger,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse } from '@nestjs/swagger';
import {
  BaseCrudController,
  type ICrudControllerService,
} from '../../bases';
import {
  createSuccessResponse,
  createErrorResponse,
  parseAdminListLimit,
  parseAdminListPage,
