class EventRegistration {}
class User {}
class SeoMeta {}

class TestPublicService extends BasePublicService {
  constructor(private readonly em: ReturnType<typeof createFakeEntityManager>) {
    super();
  }
  protected getEm() {
    return this.em as never;
  }
  protected getPostEntity() {
