    it('should persist new entity', async () => {
      const beforeCount = (em as unknown as { __all: (entity: unknown) => Array<Record<string, unknown>> }).__all('Student').length;
      const newData: Record<string, unknown> = {
        id: 'TEST-NEW-1',
        isActive: true,
      };
      const created = await service.create(newData as never);
      expect(created).toBeDefined();
      const afterCount = (em as unknown as { __all: (entity: unknown) => Array<Record<string, unknown>> }).__all('Student').length;
      expect(afterCount).toBeGreaterThanOrEqual(beforeCount);
    });
  });

  // Fixture rỗng - skip update tests

  // Module không hỗ trợ soft-delete - skip

  // Fixture rỗng - skip

  describe('bulk (với fixture thật)', () => {
    // Fixture rỗng - skip bulk delete

