import { Injectable, Logger } from '@nestjs/common';
import type {
  DatabaseSchemaResponse,
  ImportConfigResponse,
} from './system.types';

export interface ExportDataResult {
  modelOrder: string[];
  data: Record<string, unknown[]>;
